<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class PurchaseReturn extends Model { protected $fillable=['return_no','purchase_id','supplier_id','warehouse_id','user_id','total','reason']; protected $casts=['total'=>'decimal:2']; public function purchase(){return $this->belongsTo(Purchase::class);} public function supplier(){return $this->belongsTo(Supplier::class);} public function warehouse(){return $this->belongsTo(Warehouse::class);} public function user(){return $this->belongsTo(User::class);} public function items(){return $this->hasMany(PurchaseReturnItem::class);} }
